-- Purpose: Stores external navigation links configured for the customer console.
-- 用途：存储后台为用户中心配置的外部导航链接。
CREATE TABLE IF NOT EXISTS idc_portal_external_menu (
    "id" BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "name_zh" VARCHAR(80) NOT NULL,
    "name_en" VARCHAR(80) NOT NULL,
    "icon" VARCHAR(64) NOT NULL,
    "url" VARCHAR(2048) NOT NULL,
    "sort_order" INTEGER NOT NULL DEFAULT 100,
    "status" SMALLINT NOT NULL DEFAULT 1,
    "version" INTEGER NOT NULL DEFAULT 1,
    created_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMPTZ NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT chk_idc_portal_external_menu_status CHECK ("status" IN (0, 1)),
    CONSTRAINT chk_idc_portal_external_menu_sort CHECK ("sort_order" BETWEEN 0 AND 9999),
    CONSTRAINT chk_idc_portal_external_menu_version CHECK ("version" > 0)
);

CREATE INDEX IF NOT EXISTS idx_idc_portal_external_menu_display
    ON idc_portal_external_menu ("status", "sort_order", "id");
